import Image from "next/image";
import slots from "@/content/media-slots.json";
import { getPackage } from "@/lib/pricing";
import type { SceneId } from "@/lib/lightshow/scenes";
import { SceneCanvas } from "./demo/SceneCanvas";

// MEDIA SLOTS: every place a real photo or video belongs. Until Matt adds a file
// (set `src` in src/content/media-slots.json), the slot shows a live 3D render
// generated by the site, labelled as a render.

type Slot = {
  id: string;
  kind: string;
  src: string | null;
  poster?: string | null;
  alt: string;
  note: string;
  scene?: string;
  layout?: string;
  theme: string;
};

const BLUR = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mPg4+P7DwACkAGOwb9zKAAAAABJRU5ErkJggg==";

export function MediaSlot({ id, className = "", sizes = "(min-width: 1024px) 50vw, 100vw", priority = false }: { id: string; className?: string; sizes?: string; priority?: boolean }) {
  const slot = (slots as Slot[]).find((s) => s.id === id);
  if (!slot) return null;

  if (slot.src && slot.kind === "video") {
    return (
      <div className={`relative overflow-hidden bg-[#04060b] ${className}`}>
        <video className="absolute inset-0 w-full h-full object-cover" src={slot.src} poster={slot.poster ?? undefined} muted loop playsInline autoPlay controls aria-label={slot.alt} />
      </div>
    );
  }
  if (slot.src) {
    return (
      <div className={`relative overflow-hidden bg-[#04060b] ${className}`}>
        <Image src={slot.src} alt={slot.alt} fill sizes={sizes} priority={priority} placeholder="blur" blurDataURL={BLUR} className="object-cover" />
      </div>
    );
  }

  const layout = slot.layout ? getPackage(slot.layout)?.contents : undefined;
  return (
    <div className={`relative overflow-hidden bg-[#04060b] ${className}`} data-media-slot={slot.id}>
      <div className="absolute inset-0">
        <SceneCanvas
          scene={(slot.scene as SceneId) ?? "mega"}
          layout={layout}
          selection={{ kind: "theme", name: slot.theme }}
          label={`3D render: ${slot.alt}`}
          mini={false}
        />
      </div>
      <span className="absolute bottom-2 right-2 rounded-full bg-black/55 px-2.5 py-1 text-[10px] uppercase tracking-widest text-white/70 pointer-events-none">
        3D render
      </span>
    </div>
  );
}
